package com.bank.orgbrowser;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class NestedGroupDemo {
    private static final Logger log = Logger.getLogger("OrgBrowser");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", "Mumbai"),
            new Employee("Amit", "IT", "Delhi"),
            new Employee("Karan", "IT", "Mumbai"),
            new Employee("Priya", "Sales", "Mumbai"));
        OrgBrowserService service = new OrgBrowserService();

        Map<String, Map<String, List<String>>> tree = service.byDeptThenCity(staff);
        tree.forEach((dept, cities) -> cities.forEach((city, names) ->
            log.info(() -> dept + " / " + city + " → " + names)));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final String city;
    Employee(String name, String department, String city) {
        this.name = name; this.department = department; this.city = city;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    String getCity() { return city; }
}

// ─── Would be in service/OrgBrowserService.java ───
class OrgBrowserService {
    Map<String, Map<String, List<String>>> byDeptThenCity(List<Employee> staff) {
        return staff.stream()
            .filter(e -> e.getDepartment() != null && e.getCity() != null)
            .collect(groupingBy(Employee::getDepartment,        // outer: department
                groupingBy(Employee::getCity,                    // inner: city
                    mapping(Employee::getName, toList()))));       // leaf: names
    }
}
